import { TopBanner } from "./TopBanner";

export function Navbar() {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const { scrollY } = useScroll();

  useMotionValueEvent(scrollY, "change", (latest) => {
    setScrolled(latest > 50);
  });

  const NavLink = ({ href, children, scrolled }: { href: string; children: React.ReactNode; scrolled: boolean }) => (
    <Link 
      href={href} 
      className={`group relative text-sm font-medium transition-colors ${
        scrolled ? "text-bimini-primary" : "text-white/90"
      }`}
    >
      {children}
      <span className={`absolute -bottom-1 left-0 w-0 h-0.5 transition-all duration-300 group-hover:w-full ${
        scrolled ? "bg-bimini-gold" : "bg-white"
      }`} />
    </Link>
  );

  const menuVariants = {
    closed: {
      opacity: 0,
      height: 0,
      transition: {
        duration: 0.3,
        ease: [0.22, 1, 0.36, 1] as const,
        when: "afterChildren" as const,
        staggerChildren: 0.05,
        staggerDirection: -1
      }
    },
    open: {
      opacity: 1,
      height: "auto",
      transition: {
        duration: 0.5,
        ease: [0.22, 1, 0.36, 1] as const,
        when: "beforeChildren" as const,
        staggerChildren: 0.05,
        delayChildren: 0.1
      }
    }
  };

  const itemVariants = {
    closed: { opacity: 0, x: -10 },
    open: { opacity: 1, x: 0 }
  };

  return (
    <div className="fixed w-full z-50 flex flex-col">
      <TopBanner />
      <motion.nav
        initial={{ y: -100 }}
        animate={{ y: 0 }}
        transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
        className={`w-full transition-all duration-500 ${
          scrolled 
            ? "bg-white/90 backdrop-blur-xl shadow-sm py-3 border-b border-white/20" 
            : "bg-transparent py-6"
        }`}
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        <div className="flex justify-between items-center h-16">
          <div className="flex-shrink-0 flex items-center">
            <Link href="/" className="relative block w-48 h-12 group">
              <Logo 
                className={`w-full h-full object-contain object-left transition-all duration-500 ${
                  scrolled ? "text-bimini-primary" : "text-white"
                } group-hover:opacity-80`}
              />
            </Link>
          </div>
          <div className="hidden md:flex space-x-8 items-center">
            <NavLink href="#health" scrolled={scrolled}>Lee Health Access</NavLink>
            <NavLink href="#amenities" scrolled={scrolled}>Amenities</NavLink>
            <NavLink href="#floorplans" scrolled={scrolled}>Residences</NavLink>
            <NavLink href="#available-units" scrolled={scrolled}>Available Units</NavLink>
            <NavLink href="#tours" scrolled={scrolled}>3D Tours</NavLink>
            
            <Link
              href="https://showmojo.com/57925900f8/l/p/72794"
              target="_blank"
              rel="noopener noreferrer"
              className={`px-6 py-2.5 text-sm font-medium rounded-full transition-all duration-300 shadow-lg hover:shadow-xl hover:-translate-y-0.5 ${
                scrolled 
                  ? "bg-bimini-primary text-white hover:bg-bimini-secondary" 
                  : "bg-white text-bimini-primary hover:bg-gray-50"
              }`}
            >
              Schedule Tour
            </Link>
          </div>
          <div className="md:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className={`p-2 transition-colors ${scrolled ? "text-bimini-primary" : "text-white"}`}
            >
              {isOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>
      </div>

        {/* Mobile menu */}
        <AnimatePresence>
          {isOpen && (
            <motion.div
              initial="closed"
              animate="open"
              exit="closed"
              variants={menuVariants}
              className="md:hidden bg-white border-b border-gray-100 overflow-hidden shadow-xl"
            >
              <div className="px-4 pt-2 pb-6 space-y-2">
                <motion.div variants={itemVariants}>
                  <Link
                    href="#health"
                    className="block px-3 py-3 text-base font-medium text-bimini-secondary hover:text-bimini-primary hover:bg-gray-50 rounded-lg transition-colors"
                    onClick={() => setIsOpen(false)}
                  >
                    Lee Health Access
                  </Link>
                </motion.div>
                <motion.div variants={itemVariants}>
                  <Link
                    href="#amenities"
                    className="block px-3 py-3 text-base font-medium text-bimini-secondary hover:text-bimini-primary hover:bg-gray-50 rounded-lg transition-colors"
                    onClick={() => setIsOpen(false)}
                  >
                    Amenities
                  </Link>
                </motion.div>
                <motion.div variants={itemVariants}>
                  <Link
                    href="#floorplans"
                    className="block px-3 py-3 text-base font-medium text-bimini-secondary hover:text-bimini-primary hover:bg-gray-50 rounded-lg transition-colors"
                    onClick={() => setIsOpen(false)}
                  >
                    Residences
                  </Link>
                </motion.div>
                <motion.div variants={itemVariants}>
                  <Link
                    href="#available-units"
                    className="block px-3 py-3 text-base font-medium text-bimini-secondary hover:text-bimini-primary hover:bg-gray-50 rounded-lg transition-colors"
                    onClick={() => setIsOpen(false)}
                  >
                    Available Units
                  </Link>
                </motion.div>
                <motion.div variants={itemVariants}>
                  <Link
                    href="#tours"
                    className="block px-3 py-3 text-base font-medium text-bimini-secondary hover:text-bimini-primary hover:bg-gray-50 rounded-lg transition-colors"
                    onClick={() => setIsOpen(false)}
                  >
                    3D Tours
                  </Link>
                </motion.div>
                <motion.div variants={itemVariants}>
                  <Link
                    href="https://showmojo.com/57925900f8/l/p/72794"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block w-full text-center mt-4 px-5 py-3 text-base font-medium text-white bg-bimini-primary rounded-lg hover:bg-bimini-secondary shadow-md active:scale-95 transition-all"
                    onClick={() => setIsOpen(false)}
                  >
                    Schedule Tour
                  </Link>
                </motion.div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.nav>
    </div>
  );
}

